def copy_binary(src, dst, chunk_size=4):
    chunks = 0
    with open(src, "rb") as fin, open(dst, "wb") as fout:
        while True:
            chunk = fin.read(chunk_size)
            if not chunk:
                break
            fout.write(chunk)
            chunks += 1
    return chunks

