import os

def parse_task(line):
    line = line.rstrip("\n")
    if line.startswith("[x] "):
        return {"title": line[4:], "done": True}
    if line.startswith("[ ] "):
        return {"title": line[4:], "done": False}
    raise ValueError(f"Not a task: {line}")

def load(name):
    try:
        with open(name, encoding="utf-8") as f:
            return [parse_task(line) for line in f if line.strip()]
    except FileNotFoundError:
        return []

def save(tasks, name):
    temp = name + ".tmp"
    with open(temp, "w", encoding="utf-8") as f:
        for task in tasks:
            mark = "x" if task["done"] else " "
            f.write(f"[{mark}] {task['title']}\n")
    os.replace(temp, name)

def show(tasks):
    if not tasks:
        return ["Nothing to do!"]
    lines = []
    for number, task in enumerate(tasks, start=1):
        mark = "x" if task["done"] else " "
        lines.append(f"{number}. [{mark}] {task['title']}")
    return lines

def run(name, commands):
    tasks = load(name)
    output = []
    for command in commands:
        action, _, rest = command.partition(" ")
        if action == "add" and rest:
            tasks.append({"title": rest, "done": False})
            output.append(f"Added: {rest}")
        elif action == "done":
            try:
                number = int(rest)
                if number < 1:
                    raise IndexError
                task = tasks[number - 1]
            except (ValueError, IndexError):
                output.append(f"No task {rest}")
                continue
            task["done"] = True
            output.append(f"Done: {task['title']}")
        elif action == "list":
            output.extend(show(tasks))
        elif action == "clear":
            before = len(tasks)
            tasks = [t for t in tasks if not t["done"]]
            output.append(f"Cleared {before - len(tasks)}")
        else:
            output.append("Unknown command")
    save(tasks, name)
    return output

